#!/usr/bin/env node
/**
 * Refresh the long-lived Instagram access token.
 *
 * Usage:
 *   npm run instagram:token
 *
 * Meta issues Instagram-Login tokens with a 60-day life. This exchanges the
 * current one for a fresh 60-day token. It has to be run while the current
 * token is still valid — once it lapses there is no refresh path and the token
 * must be regenerated by hand in the Meta app dashboard (see .env.example).
 *
 * The new value is printed, not written: .env.local is gitignored and also
 * lives on the VPS/Netlify side, so it is pasted in deliberately rather than
 * rewritten by a script.
 *
 * Only applies to graph.instagram.com tokens (Instagram Login). Tokens from the
 * Facebook-Login flavour are refreshed through /oauth/access_token on
 * graph.facebook.com instead.
 */
import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");

/** Minimal .env reader — the script runs outside Next.js, which is what
 *  normally loads these files. */
function readEnvFile(name) {
  let contents;
  try {
    contents = readFileSync(resolve(projectRoot, name), "utf8");
  } catch {
    return {};
  }
  const values = {};
  for (const line of contents.split("\n")) {
    const match = /^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/.exec(line);
    if (!match) continue;
    values[match[1]] = match[2].replace(/^["']|["']$/g, "").trim();
  }
  return values;
}

const fileEnv = { ...readEnvFile(".env"), ...readEnvFile(".env.local") };
const token = process.env.INSTAGRAM_ACCESS_TOKEN?.trim() || fileEnv.INSTAGRAM_ACCESS_TOKEN;

if (!token) {
  console.error(
    "No INSTAGRAM_ACCESS_TOKEN found in the environment, .env.local, or .env.\n" +
      "See .env.example for how to generate the first token."
  );
  process.exit(1);
}

const endpoint = new URL("https://graph.instagram.com/refresh_access_token");
endpoint.searchParams.set("grant_type", "ig_refresh_token");
endpoint.searchParams.set("access_token", token);

const response = await fetch(endpoint, { headers: { accept: "application/json" } });
const body = await response.text();

if (!response.ok) {
  let message = `HTTP ${response.status}`;
  try {
    const parsed = JSON.parse(body);
    if (parsed?.error?.message) message = parsed.error.message;
  } catch {
    /* Non-JSON error body — the status line is all we have. */
  }
  console.error(`Refresh failed: ${message}`);
  console.error(
    "\nIf the token has already expired, generate a new one in the Meta app dashboard:\n" +
      "  developers.facebook.com > your app > Instagram > API setup with Instagram login > Generate token"
  );
  process.exit(1);
}

const { access_token: newToken, expires_in: expiresIn } = JSON.parse(body);
const days = Math.round((expiresIn ?? 0) / 86400);

console.log(`New token valid for ~${days} days:\n`);
console.log(newToken);
console.log(
  "\nPaste it into INSTAGRAM_ACCESS_TOKEN in .env.local here AND on the server\n" +
    "(then `pm2 restart` / redeploy so the running process picks it up)."
);
